import{_ as e,o as a,c,a3 as d}from"./chunks/framework.DdpBa4_E.js";const g=JSON.parse('{"title":"元素面板篇 - 技巧集合","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/14-元素面板篇-技巧集合.md","filePath":"books/chrome-devtools/14-元素面板篇-技巧集合.md","lastUpdated":1794316978000}'),t={name:"books/chrome-devtools/14-元素面板篇-技巧集合.md"};function i(s,o,l,r,p,n){return a(),c("div",null,[...o[0]||(o[0]=[d('<h1 id="元素面板篇-技巧集合" tabindex="-1">元素面板篇 - 技巧集合 <a class="header-anchor" href="#元素面板篇-技巧集合" aria-label="Permalink to &quot;元素面板篇 - 技巧集合&quot;">​</a></h1><h2 id="_1-通过-h-来隐藏元素" tabindex="-1">1. 通过 <code>&#39;h&#39;</code> 来隐藏元素 <a class="header-anchor" href="#_1-通过-h-来隐藏元素" aria-label="Permalink to &quot;1. 通过 `&#39;h&#39;` 来隐藏元素&quot;">​</a></h2><p>按一下 <code>&#39;h&#39;</code> 就可以隐藏你在元素面板中选择的元素。再次按下 &#39;<code>h</code>&#39; 可以使它出现。某些的时候这很有用：例如你想截图，但你想去掉里面的敏感信息。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/9/1679379780c11ef3~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-拖动-放置-元素" tabindex="-1">2. 拖动 &amp; 放置 元素 <a class="header-anchor" href="#_2-拖动-放置-元素" aria-label="Permalink to &quot;2. 拖动 &amp; 放置 元素&quot;">​</a></h2><p>当你想看看页面的某一部分在 <code>DOM</code> 树的不同位置的显示效果时，只需要拖动放置它(到指定的位置)，就像在机器上的其他任何地方一样 😃</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/9/16793797bde74b62~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-使用-control-按钮-来移动元素" tabindex="-1">3. 使用 <code>control</code> (按钮) 来移动元素 <a class="header-anchor" href="#_3-使用-control-按钮-来移动元素" aria-label="Permalink to &quot;3. 使用 `control` (按钮) 来移动元素&quot;">​</a></h2><p>如果你只是想移动你当前选中的元素，在 <code>DOM</code> 结构中往上挪一点或者往下挪一点，而不是拖动和放置，你同样可以使用<code>[ctrl]</code> + <code>[⬆]</code> / <code>[ctrl]</code> + <code>[⬇]</code> (<code>[⌘]</code> + <code>[⬆]</code> / <code>[⌘]</code> + <code>[⬇]</code> on Mac).</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/9/16793797bf5d233e~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_4-元素面板中类似于基础编辑器的操作" tabindex="-1">4. 元素面板中类似于基础编辑器的操作 <a class="header-anchor" href="#_4-元素面板中类似于基础编辑器的操作" aria-label="Permalink to &quot;4. 元素面板中类似于基础编辑器的操作&quot;">​</a></h2><p>从某一点来看，我们可以拖动，放置，编辑，复制(当然，以及使用 <code>[ctrl]</code> + <code>[v]</code> 来粘贴)， 所以我们可以在元素面板里把 <code>HTML</code> 结构搞得一团糟。在任意一个编辑器中都有一个标准，那么如何撤回你的操作呢？</p><p>使用<code>[ctrl]</code> + <code>[z]</code> (<code>[⌘]</code> + <code>[z]</code> on Mac)撤销我们的任何改动。 使用 <code>[ctrl]</code> + <code>[shift]</code> + <code>[z]</code>重新编辑我们的任何修改。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/9/1679379788863b4e~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_5-shadow-editor-阴影编辑器" tabindex="-1">5. <code>Shadow editor</code> 阴影编辑器 <a class="header-anchor" href="#_5-shadow-editor-阴影编辑器" aria-label="Permalink to &quot;5. `Shadow editor` 阴影编辑器&quot;">​</a></h2><p>听起来很不吉利(译者注：阴影哪里不吉利了！)，但是它也只是一个小部件而已。你可以通过在 <code>Style</code> 面板中点击靠近 <code>box-shadow</code> 属性或者 <code>text-shadow</code> 属性的 <code>阴影方形符号</code> 来打开它：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/14/167ac17a4194c870~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_6-timing-function-editor-定时函数编辑器" tabindex="-1">6. Timing function editor 定时函数编辑器 <a class="header-anchor" href="#_6-timing-function-editor-定时函数编辑器" aria-label="Permalink to &quot;6. Timing function editor 定时函数编辑器&quot;">​</a></h2><p>也称为 <code>Cubic bezier(贝塞尔)</code> 编辑器。贝塞尔曲线是一串用来定义 <code>CSS</code> 的动画速度在整个动画过程中如何变化的 <code>魔法数值</code> 。我们将其定义为 <code>transition-timing-function</code> 或者 <code>animation-timing-function</code> CSS 属性。</p><p>像之前说的 <code>Color picker</code> 和 <code>Shadow editor</code> 一样，直接点击我们刚刚提到的属性(或者他们的简写形式：<code>trasition</code>， <code>animation</code> - 请注意：如果<code>timing</code> 函数的值没有设置在这个简写的形式中，这个符号不会显示出来)边上的曲线符号：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/14/167ac1748b45fe3f~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><blockquote><p>顺带说一句，如果你没有试过 <code>3D</code> 动画，也很简单：直接在容器元素中设置一个 <code>perspective</code> 属性。例如：在 <code>body</code> 元素中设置 <code>perspective: 200px;</code></p></blockquote><h2 id="_7-插入样式规则的按钮" tabindex="-1">7. 插入样式规则的按钮 <a class="header-anchor" href="#_7-插入样式规则的按钮" aria-label="Permalink to &quot;7. 插入样式规则的按钮&quot;">​</a></h2><p>当你把鼠标放在样式选择器的选择区域的最后时，你会看到几个让你可以快速的使用 <code>Color</code> 和 <code>Shadow</code> 编辑器添加 <code>CSS</code> 属性的按钮：</p><ul><li><code>text-shadow</code></li><li><code>box-shadow</code></li><li><code>color</code></li><li><code>background-color</code></li></ul><p>...打开相应的编辑器：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/14/167ac1748b954754~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_8-在元素面板中展开所有的子节点" tabindex="-1">8. 在元素面板中展开所有的子节点 <a class="header-anchor" href="#_8-在元素面板中展开所有的子节点" aria-label="Permalink to &quot;8. 在元素面板中展开所有的子节点&quot;">​</a></h2><p>一个一个的去点击级联的 <code>▶</code> 按钮太慢了，不如使用右击节点后的 <code>expand recursively</code> 命令：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167c99eb333a3f6c~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_9-dom-断点" tabindex="-1">9. DOM 断点 <a class="header-anchor" href="#_9-dom-断点" aria-label="Permalink to &quot;9. DOM 断点&quot;">​</a></h2><p>有时脚本修改了 <code>DOM</code> ，但修改的是哪部分？什么时候修改的呢？</p><p>这样的情况下，你就可以添加一个 <code>DOM</code> 断点：监听节点被添加或者移除 / 属性被改变。</p><ul><li><p>点击&quot;...&quot; 符号或者右击你想添加监听的元素</p></li><li><p>选择 <code>subtree modifications</code> :监听任何它内部的节点被 <code>移除</code> 或者 <code>添加</code>的事件</p></li><li><p>选择 <code>attribute modifications</code> :监听任何当前选中的节点被 <code>添加</code>，<code>移除</code> 或者 <code>被修改值</code>的事件</p></li><li><p>选择 <code>node removal</code> :监听被选中的元素被 <code>移除</code> 的事件</p></li></ul><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/168746caeae2a94e~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>页面重新加载时会记住断点。当你设置了一个或多个断点的时候，可能都忘了它们所标记的位置了。怎么找它们呢？：在 <code>Elements</code> 视图中有视觉提示，<code>Sources</code> 中也有专用列表。</p><p>有时你添加了断点的元素被隐藏在一些折叠起来的父级元素中，不要担心 - 他们会在 <code>Element</code> 中用高亮展示出来。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/168747517998eb7d~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',38)])])}const h=e(t,[["render",i]]);export{g as __pageData,h as default};
